+ * first-Epic discarded drift draw is NOT skipped by inventing a new RNG order.
+ * Supported results are repeat Athena/Common and first Cephalus/Epic only.
+ */
+export function createArchIdolFx(input) {
+  const { idol, rarity, first } = input;
+  if (!((idol === 0 && rarity === 0 && first === false) ||
+        (idol === 11 && rarity === 2 && first === true))) {
+    throw new RangeError('arch-idol-fx: result outside the specified scenarios');
+  }
+  const e = {
+    createdAtMs: finite(input.createdAtMs, 'createdAtMs'), idol, rarity, first,
+    x: finite(input.x, 'x'), y: finite(input.y, 'y'),
+    D: first ? 0 : finite(input.D, 'D'), beta: finite(input.beta, 'beta'),
+    L: input.L ?? (first ? 1600 : 1000),
+    H: input.H ?? (first ? 84 : 72), S: input.S ?? (first ? 1 : 0.8),
+  };
+  for (const key of ['L', 'H', 'S']) finite(e[key], key);
+  if (!(e.L > 0) || e.H < 0 || e.S < 0) throw new RangeError('arch-idol-fx: invalid creation constants');
